-- Wires the Atlantis gear into the Splugorth minion classes that name it.
-- Rifts World Book 2: Atlantis; see apps/character-creator/docs/surveys/atlantis.md.
--
-- One-off data script, run once per environment.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/fix-atlantis-minion-class-gear.sql
--
-- WHY. The Overlord, Powerlord and Conservator were imported before the
-- bio-wizard gear and rune weapons had rows, and their notes said to backfill
-- when those rows landed; the gear PR (#1433) added them. Nate decided on
-- 2026-09-26 to wire the book's named gear in. The Blind Warrior Women get the
-- Slaver-escort kit the book issues, and the Sunaj Assassin's armor choice
-- gains the Sunaj environmental armor, which the book names first.
--
-- MECHANICS. An equipment_starting block is inserted before a line each class
-- has exactly once, guarded on the class having none; the extraction notes
-- that asked for the backfill are rewritten to say it was done. A re-run does
-- nothing. The name sorts after every add-*-class.sql it edits.

UPDATE imported_classes SET markdown = replace(markdown, '' || char(10) || 'special_abilities:' || char(10) || '', '' || char(10) || 'equipment_starting:' || char(10) || '  - { item_id: "staff-of-pacification", qty: 1 }' || char(10) || '  - { item_id: "overlord-power-armor", qty: 1 }' || char(10) || '  - { item_id: "purirobes", qty: 1 }' || char(10) || '  - { item_id: "clotrobes", qty: 2 }' || char(10) || 'special_abilities:' || char(10) || ''), updated_at = datetime('now') WHERE class_id = 'splugorth-overlord' AND instr(markdown, 'equipment_starting:') = 0;

UPDATE imported_classes SET markdown = replace(markdown, 'None has a gear row yet (bio-wizard gear is survey batch 6), so nothing is stored in equipment_starting; the list is in the body. Backfill when those rows land.', 'The staff, power armor, purirobe and clotrobes are equipment_starting since fix-atlantis-minion-class-gear.sql, once batch 6 gave them gear rows; the two further devices of choice and the police zombitrons stay in the body.'), updated_at = datetime('now') WHERE class_id = 'splugorth-overlord' AND instr(markdown, 'None has a gear row yet (bio-wizard gear is survey batch 6), so nothing is stored in equipment_starting; the list is in the body. Backfill when those rows land.') > 0;

UPDATE imported_classes SET markdown = replace(markdown, '' || char(10) || 'special_abilities:' || char(10) || '', '' || char(10) || 'equipment_starting:' || char(10) || '  - { item_id: "staff-of-power", qty: 1 }' || char(10) || '  - { item_id: "overlord-power-armor", qty: 1 }' || char(10) || '  - { item_id: "psi-interrogator", qty: 1 }' || char(10) || '  - { item_id: "purirobes", qty: 2 }' || char(10) || '  - { item_id: "clotrobes", qty: 2 }' || char(10) || '  - { item_id: "mystic-leech", qty: "1d4" }' || char(10) || '  - { item_id: "zombitron", qty: "1d4" }' || char(10) || 'special_abilities:' || char(10) || ''), updated_at = datetime('now') WHERE class_id = 'splugorth-powerlord' AND instr(markdown, 'equipment_starting:') = 0;

UPDATE imported_classes SET markdown = replace(markdown, 'None has a gear row yet (survey batch 6), so equipment_starting is omitted; the list is in the body. Backfill when those rows land.', 'Stored in equipment_starting since fix-atlantis-minion-class-gear.sql: the staff, power armor, psi-interrogator, purirobes, clotrobes, 1D4 mystic leeches (the book says magic leeches) and 1D4 zombitrons (the catalog row is priced as a pair; the qty is the book''s count). The two further device types stay in the body.'), updated_at = datetime('now') WHERE class_id = 'splugorth-powerlord' AND instr(markdown, 'None has a gear row yet (survey batch 6), so equipment_starting is omitted; the list is in the body. Backfill when those rows land.') > 0;

UPDATE imported_classes SET markdown = replace(markdown, '' || char(10) || 'special_abilities:' || char(10) || '', '' || char(10) || 'equipment_starting:' || char(10) || '  - { choose: 1, label: "lesser or greater rune weapon", qty: 1, from: ["lesser-rune-weapon", "greater-rune-weapon"] }' || char(10) || '  - { item_id: "aerobes", qty: 2 }' || char(10) || '  - { item_id: "aquarobes", qty: 2 }' || char(10) || '  - { item_id: "dehibicila", qty: 2 }' || char(10) || '  - { item_id: "purirobes", qty: 2 }' || char(10) || '  - { item_id: "stasirobes", qty: 2 }' || char(10) || '  - { item_id: "mystic-leech", qty: "1d4" }' || char(10) || '  - { item_id: "zombitron", qty: "1d4+1" }' || char(10) || 'special_abilities:' || char(10) || ''), updated_at = datetime('now') WHERE class_id = 'splugorth-conservator' AND instr(markdown, 'equipment_starting:') = 0;

UPDATE imported_classes SET markdown = replace(markdown, 'Only Lesser Rune Weapon has a gear row; the choice needs a greater rune weapon row and the bio-wizard items have none (survey batches 6-7), so equipment_starting is omitted and the list is in the body. Backfill when those rows land.', 'Stored in equipment_starting since fix-atlantis-minion-class-gear.sql: the rune weapon choice and the microbe, leech and zombitron doses (the zombitron row is priced as a pair; the qty is the book''s count). The 50% pathic healer stays in the body.'), updated_at = datetime('now') WHERE class_id = 'splugorth-conservator' AND instr(markdown, 'Only Lesser Rune Weapon has a gear row; the choice needs a greater rune weapon row and the bio-wizard items have none (survey batches 6-7), so equipment_starting is omitted and the list is in the body. Backfill when those rows land.') > 0;

UPDATE imported_classes SET markdown = replace(markdown, '' || char(10) || 'natural_abilities:' || char(10) || '', '' || char(10) || 'equipment_starting:' || char(10) || '  - { choose: 1, label: "vibro-blade", qty: 1, from: ["vibro-knife", "vibro-sword"], note: "Standard issue when accompanying a Splugorth Slaver; the book says vibro-blade without naming one." }' || char(10) || '  - { item_id: "slavers-net-gun", qty: 1 }' || char(10) || '  - { item_id: "kittani-laser-wrist-blasters", qty: 1 }' || char(10) || '  - { item_id: "bio-wizard-mental-incapacitator", qty: 1 }' || char(10) || 'natural_abilities:' || char(10) || ''), updated_at = datetime('now') WHERE class_id = 'blind-warrior-women' AND instr(markdown, 'equipment_starting:') = 0;

UPDATE imported_classes SET markdown = replace(markdown, '|| EQUIPMENT: not stored. A dagger, vibro-blade, net gun, laser wrist blaster and mental incapacitator are standard issue only to warriors accompanying a Splugorth Slaver, and a player character is typically a rogue; the net gun, mental incapacitator, padded armor and bio-wizard devices have no gear rows. Listed in the body.', '|| EQUIPMENT: the Slaver-escort kit (vibro-blade, net gun, laser wrist blasters, mental incapacitator) is equipment_starting since fix-atlantis-minion-class-gear.sql, by Nate''s decision to wire the book''s named gear in; a rogue may simply not have it. The plain dagger and the 30 M.D.C. padded suit have no rows and stay in the body.'), updated_at = datetime('now') WHERE class_id = 'blind-warrior-women' AND instr(markdown, '|| EQUIPMENT: not stored. A dagger, vibro-blade, net gun, laser wrist blaster and mental incapacitator are standard issue only to warriors accompanying a Splugorth Slaver, and a player character is typically a rogue; the net gun, mental incapacitator, padded armor and bio-wizard devices have no gear rows. Listed in the body.') > 0;

UPDATE imported_classes SET markdown = replace(markdown, 'from: ["ca-4-standard-dead-boy-armor", "gladiator-full-environmental-body-armor", "crusader-full-environmental-body-armor", "bushman-full-composite-environmental-body-armor"], note: "The book''s first choice is Sunaj assassin environmental armor (110 M.D.C.), which has no gear row yet; these are the alternatives it names." }', 'from: ["sunaj-environmental-armor", "ca-4-standard-dead-boy-armor", "gladiator-full-environmental-body-armor", "crusader-full-environmental-body-armor", "bushman-full-composite-environmental-body-armor"], note: "The book''s first choice is the Sunaj assassin environmental armor; the others are the alternatives it names." }'), updated_at = datetime('now') WHERE class_id = 'sunaj-assassin' AND instr(markdown, 'from: ["ca-4-standard-dead-boy-armor", "gladiator-full-environmental-body-armor", "crusader-full-environmental-body-armor", "bushman-full-composite-environmental-body-armor"], note: "The book''s first choice is Sunaj assassin environmental armor (110 M.D.C.), which has no gear row yet; these are the alternatives it names." }') > 0;

-- Read the result back.
SELECT 'splugorth-overlord carries its equipment' AS assertion, count(*) AS got, 1 AS want FROM imported_classes WHERE class_id = 'splugorth-overlord' AND instr(markdown, 'equipment_starting:') > 0;
SELECT 'splugorth-powerlord carries its equipment' AS assertion, count(*) AS got, 1 AS want FROM imported_classes WHERE class_id = 'splugorth-powerlord' AND instr(markdown, 'equipment_starting:') > 0;
SELECT 'splugorth-conservator carries its equipment' AS assertion, count(*) AS got, 1 AS want FROM imported_classes WHERE class_id = 'splugorth-conservator' AND instr(markdown, 'equipment_starting:') > 0;
SELECT 'blind-warrior-women carries its equipment' AS assertion, count(*) AS got, 1 AS want FROM imported_classes WHERE class_id = 'blind-warrior-women' AND instr(markdown, 'equipment_starting:') > 0;
SELECT 'sunaj-assassin offers the Sunaj armor' AS assertion, count(*) AS got, 1 AS want FROM imported_classes WHERE class_id = 'sunaj-assassin' AND instr(markdown, '"sunaj-environmental-armor"') > 0;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('fix-atlantis-minion-class-gear.sql');
